            .arg(arg)
            .try_get_matches_from(vec!["", "some-val"])
            .unwrap();
        assert_eq!(m.get_one::<String>("some-arg").unwrap(), "some-val");
    }

    #[test]
    // allow double quoted dashed arg value in triangle brackets (e.g <"some-val">)
