#[inline]
pub fn get_num_args(&self) -> Option<ValueRange> {
    self.num_vals
}

#[inline]
pub(crate) fn get_min_vals(&self) -> usize {
    self.get_num_args().expect(INTERNAL_ERROR_MSG).min_values()
}

