use clap::{arg, error::ErrorKind, Command};

#[test]
fn scratch_named_multi() {
    let a = arg!(--copy <SRC> <DST> [MODE]);
    assert_eq!(
        a.get_value_names()
            .unwrap()
            .iter()
            .map(|s| s.to_string())
            .collect::<Vec<_>>(),
        vec!["SRC", "DST", "MODE"]
    );
    assert_eq!(a.get_num_args(), Some((2..=3).into()));

    let cmd = Command::new("tool").arg(arg!(--copy <SRC> <DST> [MODE]));

    let m = cmd
        .clone()
        .try_get_matches_from(["tool", "--copy", "a", "b"])
        .unwrap();
    let vals: Vec<&String> = m.get_many::<String>("copy").unwrap().collect();
    assert_eq!(vals, vec!["a", "b"]);

    let m = cmd
        .clone()
        .try_get_matches_from(["tool", "--copy", "a", "b", "fast"])
        .unwrap();
    let vals: Vec<&String> = m.get_many::<String>("copy").unwrap().collect();
    assert_eq!(vals, vec!["a", "b", "fast"]);

    let err = cmd
        .clone()
        .try_get_matches_from(["tool", "--copy", "a"])
        .unwrap_err();
    assert_eq!(err.kind(), ErrorKind::TooFewValues);

    let err = cmd
        .clone()
        .try_get_matches_from(["tool", "--copy", "a", "b", "fast", "x"])
        .unwrap_err();
    assert_eq!(err.kind(), ErrorKind::TooManyValues);

    let help = cmd.render_help().to_string();
    println!("HELP:\n{help}");
    assert!(help.contains("--copy <SRC> <DST> [MODE]"));
}

#[test]
fn scratch_positional_multi() {
    let cmd = Command::new("tool").arg(arg!(files: <IN> [OUT]));

    let m = cmd
        .clone()
        .try_get_matches_from(["tool", "a"])
        .unwrap();
    let vals: Vec<&String> = m.get_many::<String>("files").unwrap().collect();
    assert_eq!(vals, vec!["a"]);

    let m = cmd
        .clone()
        .try_get_matches_from(["tool", "a", "b"])
        .unwrap();
    let vals: Vec<&String> = m.get_many::<String>("files").unwrap().collect();
    assert_eq!(vals, vec!["a", "b"]);

    let err = cmd.clone().try_get_matches_from(["tool"]).unwrap_err();
    assert_eq!(err.kind(), ErrorKind::MissingRequiredArgument);

    let help = cmd.render_help().to_string();
    println!("HELP:\n{help}");
    assert!(help.contains("<IN> [OUT]"));
}

#[test]
fn scratch_other_forms() {
    // id from first value name when omitted
    let a = arg!(<A> <B>);
    assert_eq!(a.get_id(), "A");
    assert_eq!(a.get_num_args(), Some((2..=2).into()));

    // string-literal value names
    let a = arg!(--copy <"src"> [mode]);
    assert_eq!(
        a.get_value_names()
            .unwrap()
            .iter()
            .map(|s| s.to_string())
            .collect::<Vec<_>>(),
        vec!["src", "mode"]
    );
    assert_eq!(a.get_num_args(), Some((1..=2).into()));

    // short + longs + help
    let a = arg!(-c --copy <SRC> <DST> "do the copy");
    assert_eq!(a.get_short(), Some('c'));
    assert_eq!(a.get_long(), Some("copy"));
    assert_eq!(
        a.get_help().map(|s| s.to_string()),
        Some("do the copy".to_owned())
    );
    assert_eq!(a.get_num_args(), Some((2..=2).into()));
}

#[test]
#[should_panic = "Required value placeholders must precede optional value placeholders"]
fn scratch_bad_order() {
    let _ = arg!(files: [OUT] <IN>);
}

