#[test]
fn scratch_named_multi() {
    // emulate arg!(--copy <SRC> <DST> [MODE])
    let arg = Arg::new("copy")
        .long("copy")
        .action(ArgAction::Set)
        .value_names(["SRC", "DST", "MODE"])
        .num_args(2..=3);
    assert_eq!(
        arg.get_value_names().unwrap().iter().map(|s| s.to_string()).collect::<Vec<_>>(),
        vec!["SRC", "DST", "MODE"]
    );

    let cmd = Command::new("tool").arg(arg);

    let m = cmd.clone().try_get_matches_from(["tool", "--copy", "a", "b"]).unwrap();
    let vals: Vec<&String> = m.get_many::<String>("copy").unwrap().collect();
    assert_eq!(vals, vec!["a", "b"]);

    let m = cmd.clone().try_get_matches_from(["tool", "--copy", "a", "b", "fast"]).unwrap();
    let vals: Vec<&String> = m.get_many::<String>("copy").unwrap().collect();
    assert_eq!(vals, vec!["a", "b", "fast"]);

    let err = cmd.clone().try_get_matches_from(["tool", "--copy", "a"]).unwrap_err();
    assert_eq!(err.kind(), ErrorKind::TooFewValues);

    let help = Command::new("tool")
        .arg(
            Arg::new("copy")
                .long("copy")
                .action(ArgAction::Set)
                .value_names(["SRC", "DST", "MODE"])
                .num_args(2..=3),
        )
        .render_help()
        .to_string();
    println!("HELP:\n{help}");
    assert!(help.contains("--copy <SRC> <DST> [MODE]"));
}

