#[test]
fn scratch_dots_forms() {
    // multiple fixed placeholders then ... => unbounded, min fixed
    let a = arg!(--copy <SRC> <DST> [MODE] ...);
    assert_eq!(a.get_num_args(), Some((2..).into()));
    assert!(matches!(a.get_action(), clap::ArgAction::Append));

    // single + ... keeps old behavior
    let a = arg!(<NUM> ...);
    assert_eq!(a.get_num_args(), Some((1..).into()));
    assert!(matches!(a.get_action(), clap::ArgAction::Append));

    let a = arg!(-f <NUM> ...);
    assert_eq!(a.get_num_args(), None);
    assert!(matches!(a.get_action(), clap::ArgAction::Append));

    let mut cmd = Command::new("tool").arg(arg!(--copy <SRC> <DST> ...));
    let m = cmd
        .try_get_matches_from(["tool", "--copy", "a", "b", "c", "d"])
        .unwrap();
    let vals: Vec<&String> = m.get_many::<String>("copy").unwrap().collect();
    assert_eq!(vals, vec!["a", "b", "c", "d"]);
}

#[test]
fn scratch_optional_named_chain() {
    let a = arg!(--opt [A] [B]);
    assert_eq!(a.get_num_args(), Some((0..=2).into()));
    assert!(!a.is_required_set());
    let mut cmd = Command::new("tool").arg(a);
    let m = cmd.try_get_matches_from(["tool"]).unwrap();
    assert!(m.get_many::<String>("opt").is_none());
    let m = cmd
        .try_get_matches_from(["tool", "--opt", "a"])
        .unwrap();
    assert_eq!(
        m.get_many::<String>("opt").unwrap().collect::<Vec<_>>(),
        vec!["a"]
    );
}
